import functools

def timed(func):
    @functools.wraps(func)               # copies __name__, __doc__, __wrapped__
    def wrapper(*args, **kwargs):        # accepts any signature
        result = func(*args, **kwargs)   # forwards positionally and by keyword
        return result                    # returns the value, easy to forget
    return wrapper

@timed
def add(a, b):
    """Add two numbers."""
    return a + b

print(add(1, 2), add.__name__, add.__doc__)

import functools

def retry(times=3):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except ValueError as exc:
                    last = exc
            raise last              # never swallow the final failure
        return wrapper
    return decorator

class CountCalls:
    def __init__(self, func):
        functools.update_wrapper(self, func)   # the class-form equivalent of wraps
        self.func = func
        self.calls = 0

    def __call__(self, *args, **kwargs):
        self.calls += 1
        return self.func(*args, **kwargs)

@CountCalls
def ping():
    return "pong"

ping(); ping()
print(ping.calls, ping.__name__)

