import functools, inspect

def bare(func):
    def wrapper(*a, **kw):
        return func(*a, **kw)
    return wrapper

def careful(func):
    @functools.wraps(func)
    def wrapper(*a, **kw):
        return func(*a, **kw)
    return wrapper

def greet(name: str, punct: str = "!") -> str:
    """Say hello."""
    return f"hi {name}{punct}"

print(inspect.signature(bare(greet)))
print(inspect.signature(careful(greet)))
